// Secure application with proper environment configuration
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

// ✅ Load environment variables early
require('dotenv').config();

// ✅ Environment variable validation
const validateEnvironment = () => {
  const essentialVars = {
    PORT: 'Server port',
    CORS_ORIGINS: 'Allowed CORS origins',
    RATE_LIMIT_WINDOW_MS: 'Rate limit window (minutes)',
    RATE_LIMIT_MAX_REQUESTS: 'Max requests per window'
  };

  const missing = [];
  for (const [varName, description] of Object.entries(essentialVars)) {
    if (!process.env[varName]) {
      missing.push(`${varName} (${description})`);
    }
  }

  if (missing.length > 0) {
    console.error('❌ Configuration Error: Missing environment variables:');
    missing.forEach(item => console.error(`   - ${item}`));
    process.exit(1);
  }
};

// ✅ Validate environment on startup
try {
  validateEnvironment();
  console.log('✅ Environment validation passed');
} catch (error) {
  console.error('❌ Environment validation failed:', error.message);
  process.exit(1);
}

const app = express();

// ⚠️ Security middleware with environment-aware configuration
app.use(helmet());

// ✅ Rate limiting with configurable values from environment
const rateLimitWindow = parseInt(process.env.RATE_LIMIT_WINDOW_MS || '15', 10);
const rateLimitMax = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10);

const limiter = rateLimit({
  windowMs: rateLimitWindow * 60 * 1000, // Convert minutes to ms
  max: rateLimitMax,
  message: `Too many requests, please try again in ${rateLimitWindow} minutes`
});
app.use(limiter);

// ✅ CORS configuration from environment variable
const allowedOrigins = process.env.CORS_ORIGINS ? 
  process.env.CORS_ORIGINS.split(',').map(origin => origin.trim()) : [];

const corsOptions = {
  origin: allowedOrigins,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

console.log(`✅ CORS configured for origins: ${allowedOrigins.join(', ')}`);

// ✅ Configurable request size limit
const requestSizeLimit = process.env.REQUEST_SIZE_LIMIT || '10kb';
app.use(express.json({ limit: requestSizeLimit }));
console.log(`✅ Request size limit set to: ${requestSizeLimit}`);

// 📊 Health endpoint - minimal information only
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// 🔒 Users endpoint with future authentication
app.get('/users', (req, res) => {
  // Simplified public response
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]);
});

// 🛑 Error handling middleware
app.use((err, req, res, next) => {
  console.error(`🚨 Server Error: ${err.message}`);
  console.error(err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

// ❔ 404 handler
app.use((req, res, next) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// ✅-server with configurable port
const PORT = parseInt(process.env.PORT, 10) || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running in ${ process.env.NODE_ENV || 'development'} mode`);
  console.log(`🌐 Listening on port: ${PORT}`);
  console.log(`🔒 Security: Helmet enabled, Rate Limiting active`);
  console.log(`📦 Environment: Using externalized configuration`);
});

module.exports = app;

